        vector<int> t(n);
        long long c = 0;

        for (int i = 0; i < n; i++) {
            scanf("%d", &t[i]);
        }

        // Assuming t[i] is within a known range, implement counting sort for efficiency
        int maxVal = *max_element(t.begin(), t.end());
        vector<int> count(maxVal + 1, 0);

        for (int i = 0; i < n; i++) {
            count[t[i]]++;
        }

        // Create a sorted array using the count array
        int index = 0;
        for (int i = 0; i <= maxVal; i++) {
            while (count[i] > 0) {
                t[index++] = i;
                count[i]--;
            }
        }

        for (size_t i = 0; i < t.size() - 1; i++) {
            c += t[i] * (n - i - 1);
        }

        printf("%lld\n", c);
    }

    return 0;
}

